import 'package:flutter_test/flutter_test.dart';
import 'package:amina/core/data/meal_food_catalog.dart';
import 'package:amina/features/journal/widgets/food_pictogram_painter_batch34.dart';
void main(){const ids=<String>['bahraini_muhammar','bahraini_mumawwash','bahraini_halwa'];test('B34 appends three Bahrain concepts after certified B33 baseline',(){expect(mealFoodCatalog.length,404);expect(mealFoodCatalog.take(401).length,401);expect(mealFoodCatalog.skip(401).map((e)=>e.id).toList(),ids);expect(mealFoodCatalog.map((e)=>e.id).toSet().length,404);});test('B34 labels search categories and native pictograms are complete',(){for(final id in ids){final item=mealFoodById(id);expect(item,isNotNull);expect(item!.fr,isNotEmpty);expect(item.en,isNotEmpty);expect(item.ar,isNotEmpty);expect(item.regions,contains(MealFoodRegion.gulf));expect(hasCodeFoodPictogramBatch34(id),isTrue);expect(searchMealFoods(item.fr).map((e)=>e.id),contains(id));}expect(mealFoodById('bahraini_muhammar')!.category,MealFoodCategory.breadGrain);expect(mealFoodById('bahraini_mumawwash')!.category,MealFoodCategory.breadGrain);expect(mealFoodById('bahraini_halwa')!.category,MealFoodCategory.sweetDessert);});}
